function reviewUnsaved(action){if(!dirty){action();return;}let d=$('unsavedReview');if(!d){d=document.createElement('dialog');d.id='unsavedReview';d.className='weight-dialog unsaved-review';document.body.appendChild(d);}d.innerHTML='<h2>تغییرات ارزیابی هنوز ذخیره نشده‌اند</h2><p>پیش از ادامه، درباره امتیازها و یادداشت‌های واردشده تصمیم بگیرید.</p><p id="unsavedError" class="danger" role="alert"></p><div class="actions"><button id="keepEditing">بازگشت به ارزیابی</button><button id="discardChanges">ادامه بدون ذخیره</button><button id="saveAndContinue" class="primary">ذخیره پیش‌نویس و ادامه</button></div>';d.showModal();$('keepEditing').onclick=()=>d.close();$('discardChanges').onclick=()=>{selectState(cinemaId,true);d.close();action();};$('saveAndContinue').onclick=async()=>{if(busy)return;$('saveAndContinue').disabled=true;await save('draft');if(dirty){$('unsavedError').textContent='پیش‌نویس ذخیره نشد. مشکل ثبت را برطرف کنید یا به ارزیابی برگردید.';$('saveAndContinue').disabled=false;return;}d.close();action();};}
function compactProfile(){const warning=[...$('content').querySelectorAll('.profile-analytics~section.card')].find(el=>el.querySelector('h2')?.textContent==='هشدارها و استثناها');if(warning){warning.classList.add('profile-header-alerts');$('content').querySelector('.profile-header').appendChild(warning);}const cards=[...$('content').querySelectorAll('.profile-analytics~section.card')];if(!cards.length)return;const grid=document.createElement('div');grid.className='profile-inspector-grid';cards[0].before(grid);cards.forEach(card=>{const d=document.createElement('details'),title=card.querySelector('h2');d.className='profile-inspector';const summary=document.createElement('summary');summary.textContent=title?.textContent||'جزئیات';if(title)title.remove();d.appendChild(summary);d.appendChild(card);grid.appendChild(d);});}
function profileCharts(a){const colors=['#10b98a','#4285ed','#9a64d8','#f3ac31','#2babc2','#ef736e'];const rows=a.categories.map((x,i)=>'<g transform="translate(0,'+(i*48)+')"><text x="635" y="18" text-anchor="end">'+h(x.name)+'</text><rect x="55" y="28" width="580" height="8" rx="4" fill="#eef2f7"/><rect x="55" y="28" width="'+((x.score??0)/5*580)+'" height="8" rx="4" fill="'+colors[i]+'"/><text x="30" y="33" text-anchor="middle">'+fmt(x.score)+'</text></g>').join('');return '<section class="profile-analytics"><div><h2>نمای عملکرد شاخص‌ها</h2><svg role="img" aria-label="نمودار امتیاز شاخص‌های سینما" viewBox="0 0 680 310">'+rows+'</svg></div><div class="coverage-donut" style="--coverage:'+a.coverage*100+'%"><div><strong>'+n(a.coverage*100,0)+'٪</strong><span>پوشش ارزیابی</span></div><p>'+n(a.completed)+' ردیف بررسی‌شده<br>'+n(a.required-a.completed)+' ردیف در انتظار</p></div></section>';}
