 $('content').innerHTML='<section class="card"><div class="filters">'+selectCinema()+'<button id="openProfile">مشاهده پروفایل سینما</button></div><p class="content-note">ردیف‌های جدول مطابق سند هستند. نمره صفر یعنی ضعف واقعی؛ بررسی‌نشده و فاقد کاربرد دو وضعیت جدا هستند. فرمول در هر سطح: مجموع (امتیاز × وزن) ÷ مجموع وزن‌های مرتبط.</p>'+(!record(cinemaId)&&previous?'<div class="notice">برای این سینما ارزیابی نسخه '+n(previous.model_version)+' موجود است. می‌توانید پاسخ‌های ردیف‌های باقی‌مانده را به پیش‌نویس این نسخه منتقل و با وزن‌های جدید بررسی کنید؛ نسخه قبلی تغییر نمی‌کند. <button id="copyPrevious" class="small-button">انتقال پاسخ‌های نسخه قبلی به پیش‌نویس</button></div>':'')+'</section><div class="summary-strip"><div><strong id="liveScore">'+fmt(a.score)+'</strong> <small>از ۵</small><p id="liveCoverage">'+n(a.completed)+' از '+n(a.required)+' ردیف مرتبط · پوشش '+n(a.coverage*100,1)+'٪</p></div><div><span id="dirtyLabel" class="badge '+(dirty?'amber':'')+'">'+(dirty?'تغییرات ذخیره‌نشده':'ذخیره‌شده')+'</span><p id="liveStatus">'+(a.ready?'پاسخ‌ها کامل؛ قابل نهایی‌سازی':'امتیاز موقت؛ ارزیابی کامل نشده')+'</p></div><div class="actions"><button id="saveDraft" '+(busy?'disabled':'')+'>ذخیره پیش‌نویس</button><button id="saveFinal" class="primary" '+(busy||!a.ready?'disabled':'')+'>ثبت نهایی ارزیابی</button></div></div><details class="card"><summary>مشخصات و ظرفیت سینما — اطلاعات پروفایل این ارزیابی</summary><p class="content-note">این اطلاعات با ارزیابی ذخیره می‌شوند؛ امتیازهای قدیمی و اطلاعات پایه داشبورد قبلی بازنویسی نمی‌شوند.</p><div class="field-grid">'+(model.profileFields||[]).map(f=>'<label>'+h(f.title)+'<input class="profile-field" data-field="'+h(f.id)+'" type="'+(f.type==='number'?'number':'text')+'" '+(f.type==='number'?'min="0"':'')+' value="'+h(context.profile?.[f.id]??current()?.[f.id]??'')+'"></label>').join('')+'</div></details><nav class="eval-rail">'+model.sections.map(x=>'<a href="#eval-'+x.id+'">'+h(x.name)+'</a>').join('')+'</nav>'+model.sections.map(s=>'<section id="eval-'+s.id+'" class="eval-section"><div class="section-head"><div><h2>'+h(s?.name||'')+'</h2><p class="content-note">'+h(s?.description||'')+'</p></div><span class="badge">وزن شاخص '+n((s?.weight||0)*100,1)+'٪</span></div><div class="evaluationGroups">'+(s?.groups||[]).map((g,i)=>{const gr=a.categories.find(c=>c.id===s.id)?.groups.find(x=>x.id===g.id);return '<details class="group-card" '+(i===0?'open':'')+'><summary><span>'+h(g.name)+' <small class="muted">· وزن '+n(g.weight*100,1)+'٪</small></span><b class="table-score" data-group-score="'+g.id+'">'+fmt(gr?.score)+'</b></summary><div class="group-body"><p class="content-note">'+h(g.description)+'</p><label class="param-exclusion"><input type="checkbox" class="group-include" data-group="'+g.id+'" '+(!context.excludedParams?.includes(g.id)?'checked':'')+'> احتساب این پارامتر در ارزیابی</label><input class="group-reason '+(context.excludedParams?.includes(g.id)?'':'hidden')+'" data-group="'+g.id+'" placeholder="دلیل خروج پارامتر؛ حداقل ۸ نویسه" value="'+h(context.exclusionReasons?.[g.id]||'')+'"><div class="table-wrap"><table class="criteria"><thead><tr><th>ردیف و نحوه بررسی</th><th>معیار ارزیابی</th><th>وزن ردیف</th><th>امتیاز کارشناس</th><th>توضیح و مستند</th></tr></thead><tbody>'+g.questions.map((q,j)=>{const ans=answers[q.id]||{},ref=q.tag==='reference'||q.type==='reference',info=q.type==='info',state=a.byItem.find(x=>x.id===q.id),off=state?.excluded||state?.pending;return '<tr data-eval-row="'+q.id+'" class="'+(off?'row-inactive':'')+'"><td data-label="ردیف و نحوه بررسی"><span class="criterion-number">'+n(j+1)+(q.source?' · جدول '+n(q.source.table)+'، ردیف '+n(q.source.row):' · ردیف افزوده‌شده')+'</span><b>'+h(q.name)+'</b>'+(q.tag==='critical'?' '+badge('حساس','red'):'')+'<div class="method">'+h(q.method)+'</div>'+(q.note?'<p class="content-note">'+h(q.note)+'</p>':'')+'</td><td data-label="معیار ارزیابی">'+rubric(q)+'</td><td data-label="وزن ردیف">'+n(q.weight*100,2)+'٪<small class="effective-row" data-effective="'+q.id+'">مؤثر: '+n((state?.effectiveWeight||0)*100,2)+'٪</small>'+(ref?'<p>'+badge('مرجع')+'</p>':info?'<p>'+badge('اطلاعاتی')+'</p>':'')+'</td><td data-label="امتیاز کارشناس">'+(ref?'<p class="content-note">این موضوع دوباره امتیاز نمی‌گیرد. محل محاسبه: '+h(model.sections.flatMap(s=>[s,...s.groups]).find(x=>x.id===q.referenceTo)?.name||'محل اصلی هنوز تعیین نشده')+'</p>':info?'<p class="content-note">فقط ثبت اطلاعات</p>':'<div class="score-slider"><output data-score-output="'+q.id+'">'+fmt(ans.score)+'</output><input type="range" min="0" max="5" step=".25" class="answer-score" data-question="'+q.id+'" value="'+(ans.score??0)+'" '+(ans.na||off?'disabled':'')+' aria-label="امتیاز '+h(q.name)+'"><div class="scale-ticks"><span>۰</span><span>۱</span><span>۲</span><span>۳</span><span>۴</span><span>۵</span></div><div class="score-actions"><button type="button" data-set-zero="'+q.id+'">ثبت صفر</button><button type="button" data-clear-score="'+q.id+'">پاک کردن امتیاز</button></div></div><label><input type="checkbox" class="answer-na" data-question="'+q.id+'" '+(ans.na?'checked':'')+'> این معیار برای این سینما کاربرد ندارد</label><input class="answer-reason '+(ans.na?'':'hidden')+'" data-question="'+q.id+'" value="'+h(ans.note||'')+'" placeholder="علت کاربرد نداشتن معیار را توضیح دهید">')+'</td><td data-label="توضیح و مستند"><textarea class="answer-evidence" data-question="'+q.id+'" placeholder="مشاهده کارشناس / نشانی مستند">'+h(ans.evidence||'')+'</textarea></td></tr>';}).join('')+'</tbody></table></div></div></details>';}).join('')+'</div></section>').join('')+'<section class="card"><h3>محاسبه زنده شاخص‌ها</h3><div id="liveAxes">'+liveAxes(a)+'</div><div class="formula">Parameter = Σ(row score × row weight) / Σ(active row weights)</div><p class="content-note">برای شاخص و سینما همین فرمول با وزن پارامترها و وزن شاخص‌ها اعمال می‌شود. تعداد ردیف‌های یک جدول به‌تنهایی وزن پارامتر را زیاد نمی‌کند.</p><div id="liveWarnings"></div></section>';
 if($('copyPrevious'))$('copyPrevious').onclick=()=>{if(dirty&&!confirm('پاسخ‌های ذخیره‌نشده با نسخه قبلی جایگزین شوند؟'))return;answers=tools.carryResponses(model,previous.responses);context=clone(previous.profile_snapshot||{});context.amenities=context.amenities||{};change();evaluate();toast('پاسخ‌ها به پیش‌نویس منتقل شدند؛ تغییر معیارها و ردیف‌های جدید را بازبینی کنید. هنوز ذخیره نشده‌اند.');};
